'use client';

import React, { useState, useEffect } from 'react';
import { initAudio, setSoundEnabled, getSoundEnabled, playNodeActivate } from '../utils/sound';

export default function Navbar({ onOpenSearch }) {
  const [scrolled, setScrolled] = useState(false);
  const [sfxEnabled, setSfxEnabled] = useState(false);

  useEffect(() => {
    setSfxEnabled(getSoundEnabled());
    const handleScroll = () => {
      setScrolled(window.scrollY > 40);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <header
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 100,
        padding: scrolled ? '12px 24px' : '20px 24px',
        transition: 'all 0.3s ease',
        background: scrolled ? 'rgba(7, 9, 14, 0.85)' : 'transparent',
        backdropFilter: scrolled ? 'blur(16px)' : 'none',
        WebkitBackdropFilter: scrolled ? 'blur(16px)' : 'none',
        borderBottom: scrolled ? '1px solid rgba(255, 255, 255, 0.08)' : '1px solid transparent',
      }}
    >
      <div
        className="container-custom"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        {/* Brand / Moniker */}
        <a
          href="#act-hero"
          style={{
            textDecoration: 'none',
            display: 'flex',
            alignItems: 'center',
            gap: '12px',
          }}
        >
          <span
            style={{
              fontFamily: 'var(--font-mono)',
              fontWeight: 700,
              fontSize: '0.90rem',
              letterSpacing: '0.08em',
              color: '#ffffff',
            }}
          >
            SHREYANS JAIN
          </span>
          <span
            style={{
              fontFamily: 'var(--font-mono)',
              fontSize: '0.70rem',
              padding: '2px 8px',
              borderRadius: '4px',
              background: 'rgba(56, 189, 248, 0.12)',
              color: '#38bdf8',
              border: '1px solid rgba(56, 189, 248, 0.25)',
            }}
          >
            AI ARCHITECT
          </span>
        </a>

        {/* Center Links (Desktop) */}
        <nav
          style={{
            display: 'none',
            gap: '24px',
            alignItems: 'center',
          }}
          className="desktop-nav"
        >
          <a href="#act-hero" style={{ color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '0.84rem' }}>
            Core
          </a>
          <a href="#act-rag" style={{ color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '0.84rem' }}>
            RAG
          </a>
          <a href="#act-agentic" style={{ color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '0.84rem' }}>
            Agentic
          </a>
          <a href="#act-voice" style={{ color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '0.84rem' }}>
            Voice AI
          </a>
          <a href="#act-video" style={{ color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '0.84rem' }}>
            Veo Studio
          </a>
          <a href="#act-systems" style={{ color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '0.84rem' }}>
            Systems
          </a>
          <a href="#act-journey" style={{ color: 'var(--text-secondary)', textDecoration: 'none', fontSize: '0.84rem' }}>
            Journey
          </a>
        </nav>

        {/* Right Actions */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          {/* Quick Search Cmd+K Trigger */}
          <button
            onClick={() => {
              if (onOpenSearch) onOpenSearch();
            }}
            className="nav-search-btn"
            title="Open Command Palette (Cmd+K)"
          >
            <span>🔍</span>
            <span className="nav-search-label">Search</span>
            <kbd className="nav-search-kbd">⌘K</kbd>
          </button>

          {/* SFX Toggle */}
          <button
            onClick={() => {
              const next = !sfxEnabled;
              setSfxEnabled(next);
              setSoundEnabled(next);
              if (next) {
                initAudio();
                playNodeActivate();
              }
            }}
            className={`nav-sfx-btn ${sfxEnabled ? 'active' : ''}`}
            title={sfxEnabled ? 'Sound Effects Enabled (Click to Mute)' : 'Sound Effects Muted (Click to Enable)'}
          >
            <span>{sfxEnabled ? '🔊' : '🔇'}</span>
            <span className="nav-sfx-label">{sfxEnabled ? 'SFX ON' : 'SFX'}</span>
          </button>

          <a
            href="#act-contact"
            className="btn-primary"
            style={{
              padding: '8px 18px',
              fontSize: '0.84rem',
            }}
          >
            Connect →
          </a>
        </div>
      </div>

      <style jsx>{`
        @media (min-width: 900px) {
          .desktop-nav {
            display: flex !important;
          }
          #nav-status-pill {
            display: inline-flex !important;
          }
        }
      `}</style>
    </header>
  );
}
