'use client';

import React, { useState } from 'react';

export default function VideoScreen() {
  const [activeFrame, setActiveFrame] = useState(2);
  const frames = ['Frame #01: Script', 'Frame #02: Storyboard', 'Frame #03: Veo Motion', 'Frame #04: QA Verify'];

  const nextFrame = () => {
    setActiveFrame((prev) => (prev + 1) % frames.length);
  };

  return (
    <div className="screen-panel-inner">
      <div style={{ marginBottom: '6px' }}>
        <span style={{ fontSize: '0.68rem', color: '#64748b', textTransform: 'uppercase', display: 'block' }}>
          MULTIMODAL AI FILM STUDIO
        </span>
        <span style={{ fontFamily: 'var(--font-mono)', fontSize: '0.84rem', color: '#f8fafc', fontWeight: 600 }}>
          Google Veo + 4-Agent Continuity DAG
        </span>
      </div>

      <div className="video-studio-container">
        <div className="video-frame-preview">
          <div className="video-scanline"></div>
          <div style={{ textAlign: 'center', zIndex: 5 }}>
            <div style={{ fontSize: '1.8rem', marginBottom: '4px' }}>🎬</div>
            <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.78rem', color: '#60a5fa', fontWeight: 600 }}>
              {frames[activeFrame]}
            </div>
            <span style={{ fontSize: '0.68rem', color: '#94a3b8' }}>Style Locked · Character Consistency 100%</span>
          </div>
        </div>

        <div className="video-timeline-reel">
          {frames.map((f, i) => (
            <div
              key={f}
              className={`video-keyframe ${activeFrame === i ? 'active' : ''}`}
              onClick={() => setActiveFrame(i)}
              style={{ cursor: 'pointer' }}
            >
              Keyframe 0{i + 1}
            </div>
          ))}
        </div>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: '0.68rem', fontFamily: 'var(--font-mono)', color: '#38bdf8' }}>
            ⚡ 80% Production Cycle Reduction
          </span>
          <button
            onClick={nextFrame}
            style={{
              padding: '3px 8px',
              fontSize: '0.68rem',
              background: 'rgba(59, 130, 246, 0.15)',
              border: '1px solid rgba(59, 130, 246, 0.3)',
              color: '#60a5fa',
              borderRadius: '6px',
              cursor: 'pointer',
              fontFamily: 'var(--font-mono)',
            }}
          >
            ▶ Advance Sequence
          </button>
        </div>
      </div>
    </div>
  );
}
