'use client';

import React, { useEffect, useState } from 'react';

export default function SynapticScrollNavigator() {
  const [scrollProgress, setScrollProgress] = useState(0);
  const [activeStage, setActiveStage] = useState({
    tag: 'ORIGIN // APEX CORE',
    title: 'AI Systems Architecture',
    why: 'Autonomous agent swarms, low-latency voice, and enterprise RAG at scale',
    color: '#38bdf8',
  });

  const stages = [
    {
      id: 'act-hero',
      threshold: 0,
      tag: 'STAGE 00 // APEX ORIGIN',
      title: 'Autonomous System Core',
      why: 'Bleeding-edge research translated into resilient production architectures',
      color: '#38bdf8',
    },
    {
      id: 'act-rag',
      threshold: 0.12,
      tag: 'STAGE 01 // KNOWLEDGE RAG',
      title: 'Enterprise Knowledge Systems',
      why: 'Dense + BM25 hybrid search cutting inquiry time from 60+ mins to <1 min',
      color: '#10b981',
    },
    {
      id: 'act-agentic',
      threshold: 0.24,
      tag: 'STAGE 02 // AGENTIC SWARMS',
      title: 'Stateful Multi-Agent DAGs',
      why: 'LangGraph autonomous routing with self-healing SQL and <2% error loop',
      color: '#a855f7',
    },
    {
      id: 'act-voice',
      threshold: 0.36,
      tag: 'STAGE 03 // REALTIME AUDIO',
      title: 'Low-Latency Voice AI',
      why: 'Full-duplex WebSocket streaming with Whisper STT and <400ms turnaround',
      color: '#f59e0b',
    },
    {
      id: 'act-video',
      threshold: 0.48,
      tag: 'STAGE 04 // MULTIMODAL VIDEO',
      title: 'Agentic Film Studio',
      why: 'Google Veo script-to-screen pipeline cutting production cycles by 80%',
      color: '#3b82f6',
    },
    {
      id: 'proj-flipkart',
      threshold: 0.58,
      tag: 'SYSTEM 01 // FLIPKART TALK2DATA',
      title: 'Natural Language SQL Analytics',
      why: 'Zero-shot schema reflection for non-technical retail category managers',
      color: '#38bdf8',
    },
    {
      id: 'proj-rag',
      threshold: 0.65,
      tag: 'SYSTEM 02 // PRODUCTION RAG',
      title: 'Enterprise Manuals Search',
      why: '98.4% faithfulness across 100+ page PDFs with DeepEval validation',
      color: '#10b981',
    },
    {
      id: 'proj-voice',
      threshold: 0.72,
      tag: 'SYSTEM 03 // CONVERSATIONAL VOICE',
      title: 'Automated Support & Bookings',
      why: '5 concurrent full-duplex streams with 100% automated customer scheduling',
      color: '#f59e0b',
    },
    {
      id: 'proj-video',
      threshold: 0.78,
      tag: 'SYSTEM 04 // VEO VIDEO PIPELINE',
      title: 'Continuous Frame Synthesis',
      why: 'Director, Storyboard, and QA agents ensuring 100% character lock',
      color: '#3b82f6',
    },
    {
      id: 'proj-creativium',
      threshold: 0.83,
      tag: 'SYSTEM 05 // CREATIVIUM AD-TECH',
      title: 'Campaign-Ready Asset Engine',
      why: 'Imagen 3 layout adaptation delivering 10x marketing asset velocity',
      color: '#fbbf24',
    },
    {
      id: 'proj-rfp',
      threshold: 0.88,
      tag: 'SYSTEM 06 // RFP DOC INTELLIGENCE',
      title: 'Gemini 1.5 Pro Bid Automation',
      why: 'Accelerated RFP turnarounds by 75% with zero-risk SLA extraction',
      color: '#38bdf8',
    },
    {
      id: 'act-journey',
      threshold: 0.92,
      tag: 'TRAJECTORY // CAREER ODYSSEY',
      title: '5-Phase Chronology',
      why: 'dentsu · BUSINESSNEXT · Christ University Lecturer · VIT Vellore',
      color: '#a855f7',
    },
    {
      id: 'act-contact',
      threshold: 0.97,
      tag: 'CONNECT // EXECUTIVE SUITE',
      title: 'Direct Strategic Access',
      why: 'Available for Senior/Staff Applied AI Engineer & Architect roles',
      color: '#10b981',
    },
  ];

  useEffect(() => {
    const handleScroll = () => {
      const scrollY = window.scrollY;
      const maxScroll = document.documentElement.scrollHeight - window.innerHeight;
      const progress = maxScroll > 0 ? scrollY / maxScroll : 0;
      setScrollProgress(progress);

      // Find current stage
      let current = stages[0];
      for (let i = stages.length - 1; i >= 0; i--) {
        if (progress >= stages[i].threshold) {
          current = stages[i];
          break;
        }
      }
      setActiveStage(current);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToStage = (id) => {
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <>
      {/* Right-Side Vertical Synaptic Spine & Jumping Particle */}
      <aside
        className="synaptic-spine-container"
        aria-label="Interactive Story Navigator"
      >
        {/* Background Guide Line */}
        <div className="spine-track-bg"></div>

        {/* Illuminated Trace Line (Leaves the trace behind as you scroll) */}
        <div
          className="spine-trace-fill"
          style={{
            height: `${Math.min(scrollProgress * 100, 100)}%`,
            background: `linear-gradient(to bottom, #38bdf8, ${activeStage.color})`,
            boxShadow: `0 0 12px ${activeStage.color}`,
          }}
        ></div>

        {/* Traveling Particle (The main character orb) */}
        <div
          className="synaptic-particle-orb"
          style={{
            top: `${Math.min(scrollProgress * 100, 99)}%`,
            borderColor: activeStage.color,
            boxShadow: `0 0 18px ${activeStage.color}, 0 0 32px ${activeStage.color}88`,
          }}
        >
          <span
            className="particle-core"
            style={{ background: activeStage.color }}
          ></span>
        </div>

        {/* Milestone Node Dots Along the Spine */}
        {stages.map((st) => {
          const isPassed = scrollProgress >= st.threshold;
          return (
            <button
              key={st.id}
              onClick={() => scrollToStage(st.id)}
              className={`spine-waypoint-dot ${isPassed ? 'passed' : ''}`}
              style={{
                top: `${st.threshold * 100}%`,
                borderColor: isPassed ? st.color : 'rgba(255,255,255,0.2)',
                background: isPassed ? st.color : '#07090e',
              }}
              title={st.title}
              aria-label={`Jump to ${st.title}`}
            ></button>
          );
        })}
      </aside>

      {/* Floating Storyline Context HUD (Tells user WHAT they are reading and WHY) */}
      <div className="synaptic-hud-pill">
        <div className="hud-pill-inner">
          <div className="hud-pill-left">
            <span
              className="hud-pulse-radar"
              style={{ background: activeStage.color, boxShadow: `0 0 10px ${activeStage.color}` }}
            ></span>
            <div>
              <span className="hud-tag" style={{ color: activeStage.color }}>
                {activeStage.tag}
              </span>
              <div className="hud-title">{activeStage.title}</div>
            </div>
          </div>
          <div className="hud-why-bubble">
            <span className="hud-why-label">CONTEXT:</span>
            <span className="hud-why-text">{activeStage.why}</span>
          </div>
        </div>
      </div>
    </>
  );
}
